const normalizarWa = n => { const d = String(n || '').replace(/\D/g, ''); if (!d) return ''; return '+' + (d.length === 10 ? '549' + d : d); };

const updates = [], nuevos = [], hallazgos = [], crudas = [], avisos = [];
